(()=>{document.querySelectorAll('.journey-picker').forEach(picker=>{const preview=picker.querySelector('.journey-preview p');picker.querySelectorAll('.journey-choice').forEach(a=>{const show=()=>{preview.textContent=a.dataset.description;};a.addEventListener('pointerenter',show);a.addEventListener('focus',show);});if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){picker.classList.add('arrived');observer.disconnect();}},{threshold:.15});observer.observe(picker);}});})();
